.env
</FILEPATH>
<CODE>
APP_NAME=Lumen
APP_ENV=local
APP_KEY=
APP_DEBUG=true
APP_URL=http://localhost

LOG_CHANNEL=stack

DB_CONNECTION=sqlite
DB_DATABASE=/app/db.sqlite3

CACHE_DRIVER=file
QUEUE_CONNECTION=sync

APP_SECRET=your_app_secret_here
</CODE>

